pub fn get_quest_ui_map_id(quest_id: u32) -> u32 {
    QUEST_UI_MAP.get(&quest_id).copied().unwrap_or(0)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_quest_ui_map_count() {
        assert!(QUEST_UI_MAP.len() > 15000);
    }

    #[test]
    fn test_known_quest() {
        // Quest 11 has ObjectiveIndex=-1 row with UiMapID=37
        assert_eq!(get_quest_ui_map_id(11), 37);
    }

    #[test]
    fn test_unknown_quest() {
        assert_eq!(get_quest_ui_map_id(999_999_999), 0);
    }
}
